import{_ as a,o,c as i,aa as t}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/media/cs/diary/m_podepis.jpg",k=JSON.parse('{"title":"Podepisování v mobilu","description":"","frontmatter":{"title":"Podepisování v mobilu","wiki":"cs:diary:m_signing"},"headers":[],"relativePath":"diary/m_signing.md","filePath":"diary/m_signing.md","lastUpdated":1794209661000}'),p={name:"diary/m_signing.md"};function s(r,e,l,d,u,v){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="podepisovani-v-mobilu" tabindex="-1">Podepisování v mobilu <a class="header-anchor" href="#podepisovani-v-mobilu" aria-label="Permalink to &quot;Podepisování v mobilu&quot;">​</a></h1><p>V mobilní aplikaci podepíšete své Další záznamy i celý den stejně jako na webu. Podepisujete tím způsobem, který máte nastavený na svém účtu – nastavení je společné pro web i mobil.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/mobilni-aplikace-denik">Psát deník v mobilu</a> v Akademii.</p><h2 id="co-se-podepisuje" tabindex="-1">Co se podepisuje <a class="header-anchor" href="#co-se-podepisuje" aria-label="Permalink to &quot;Co se podepisuje&quot;">​</a></h2><ul><li><strong>Další záznam</strong> – každý autor podepisuje svůj záznam sám. Podepsat ho může jen jeho autor.</li><li><strong>Den</strong> – podpisem Denního protokolu se zamkne celý den. Před podpisem dne musí být zpravidla podepsané všechny Další záznamy toho dne.</li></ul><p>Pravidla podepisování – kdo podepisuje první, v jakém pořadí se dny podepisují a kdy jde den podepsat bez podepsaných Dalších záznamů – popisuje <a href="/buildary-help-preview/diary/signing">Podepisování deníku</a>.</p><h2 id="podepsat-dalsi-zaznam" tabindex="-1">Podepsat Další záznam <a class="header-anchor" href="#podepsat-dalsi-zaznam" aria-label="Permalink to &quot;Podepsat Další záznam&quot;">​</a></h2><ol><li>V sekci <strong>Další záznamy</strong> otevřete nabídku záznamu (tři tečky vpravo nahoře).</li><li>Klepněte na <strong>Podepsat záznam</strong>.</li></ol><p>Pokud podepisujete v externí aplikaci, zvolte místo toho <strong>Stažení k elektronickému podpisu</strong>, soubor podepište a nahrajte zpět volbou <strong>Nahrej elektronicky podepsaný soubor</strong>.</p><p>Nemáte elektronický podpis? Volbou <strong>Nahrej scan tohoto zápisu</strong> nahrajete naskenovaný záznam podepsaný na papíře – viz <a href="/buildary-help-preview/diary/signingwithout">Bez elektronického podpisu</a>.</p><h2 id="podepsat-den" tabindex="-1">Podepsat den <a class="header-anchor" href="#podepsat-den" aria-label="Permalink to &quot;Podepsat den&quot;">​</a></h2><ol><li>Otevřete den, který chcete podepsat.</li><li>V horní liště otevřete nabídku dne (tři tečky vpravo).</li><li>Klepněte na <strong>Podepsat den</strong>. Při podpisu v externí aplikaci použijte <strong>Stažení k elektronickému podpisu</strong> a pak <strong>Nahrej elektronicky podepsaný soubor</strong>.</li></ol><p>Podepsaný den už nejde odemknout. Další volby nabídky dne popisuje <a href="/buildary-help-preview/diary/m_dailyentries">Denní záznamy v mobilu</a>.</p><h2 id="nastaveni-podpisu-v-mobilu" tabindex="-1">Nastavení podpisu v mobilu <a class="header-anchor" href="#nastaveni-podpisu-v-mobilu" aria-label="Permalink to &quot;Nastavení podpisu v mobilu&quot;">​</a></h2><p>Způsob podpisu a jeho vzhled změníte i v mobilu: otevřete <a href="/buildary-help-preview/diary/m_project_list">menu aplikace</a>, klepněte na <strong>Nastavení</strong> a pak na <strong>Nastavení podpisu</strong>. Co jednotlivé způsoby znamenají a který zvolit, vysvětlují <a href="/buildary-help-preview/diary/signaturesetting">Způsoby podpisu</a>.</p><figure class="shot" style="--w:260px;"><img src="'+n+'" alt="Obrazovka Nastavení podpisu v mobilu se způsoby podepisování a vzhledem podpisu" loading="lazy"></figure><p>Nastavení se ukládá k vašemu účtu. Co nastavíte na webu, platí i v mobilu, a naopak.</p><p>V mobilu se jednotlivé způsoby liší takto:</p><ul><li><strong>Buildary certifikát</strong> – podpis proběhne na serveru Buildary, v telefonu nic dalšího nepotřebujete.</li><li><strong>Kvalifikovaný certifikát</strong> – certifikát musí být v telefonu jako soubor PFX. Po zvolení této možnosti soubor vyberte v telefonu a zadejte jeho heslo; certifikát se nahraje do aplikace. Jak certifikát do telefonu dostat, popisuje <a href="/buildary-help-preview/diary/m_certificate">Certifikát v mobilu</a>.</li><li><strong>Služba RemoteSign</strong> – na webu volba <strong>Služba společnosti První certifikační autorita</strong> (I.CA). Je pro držitele kvalifikovaného certifikátu od I.CA, kteří mají službu RemoteSign zřízenou.</li><li><strong>Externí aplikace</strong> – Buildary připraví PDF, které podepíšete v jiné aplikaci v telefonu a nahrajete zpět. Vzhled podpisu určuje ta aplikace.</li></ul><p>U prvních tří způsobů si nastavte i vzhled podpisu: obrázek s textem, jen obrázek, nebo jen text. Obrázek vyberete ze souboru, nebo podpis nakreslíte prstem. Text doplní aplikace sama: vaše jméno a vaši roli v podepisovaném deníku.</p><div class="tip custom-block"><p class="custom-block-title">Změna se projeví po novém načtení</p><p>Když nastavení podpisu změníte, načtěte deník znovu – teprve pak se změna projeví.</p></div>',21)])])}const b=a(p,[["render",s]]);export{k as __pageData,b as default};
